{
  "concepts": [],
  "definitions": [
    {
      "term": {
        "text": "for each loop",
        "refs": ["Q0000"]
      },
      "definition_text": {
        "text": "A loop construct in Java used to iterate over arrays or collections without needing an explicit index or counter.",
        "refs": ["Q0000"]
      },
      "context": null
    },
    {
      "term": {
        "text": "infinite loop",
        "refs": ["Q0000", "Q0010"]
      },
      "definition_text": {
        "text": "A loop that never terminates on its own, typically created with a condition that is always true (e.g., while true) unless a break statement is used.",
        "refs": ["Q0000", "Q0010"]
      },
      "context": null
    }
  ],
  "examples": [
    {
      "exemplifies": {
        "text": "Iterating over a string array named fruits using a for each loop.",
        "refs": ["Q0002", "Q0003"]
      },
      "example_text": {
        "text": "for (String fruit : fruits) { System.out.println(fruit); }",
        "refs": ["Q0002", "Q0003"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "Validating user input for a mortgage calculator using an infinite loop with break.",
        "refs": ["Q0009"]
      },
      "example_text": {
        "text": "while (true) { // read input; if (input valid) { break; } }",
        "refs": ["Q0009"]
      },
      "example_type": null
    }
  ],
  "explanations": [
    {
      "topic": {
        "text": "Limitations of the for each loop",
        "refs": ["Q0004", "Q0005"]
      },
      "explanation_text": {
        "text": "The for each loop can only iterate forward through an array and does not provide access to the index of each element.",
        "refs": ["Q0004", "Q0005"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Need for break statement in while true loops",
        "refs": ["Q0000"]
      },
      "explanation_text": {
        "text": "When using while true, a break statement must be included inside the loop body to prevent an infinite loop that never terminates and can consume memory.",
        "refs": ["Q0000"]
      },
      "explanation_type": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "A for each loop in Java iterates over arrays or collections without requiring an explicit counter.",
        "refs": ["Q0000"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The for each loop iterates only in the forward direction; it cannot iterate from the end to the beginning of an array.",
        "refs": ["Q0004"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The for each loop does not provide access to the index of each item; only the item value is available.",
        "refs": ["Q0005"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "A while true loop without a break statement results in an infinite loop that never terminates.",
        "refs": ["Q0000"]
      },
      "fact_type": null
    }
  ],
  "formulas": [],
  "procedures": [
    {
      "procedure_name": {
        "text": "Validate numeric input using an infinite loop",
        "refs": ["Q0009"]
      },
      "steps": [
        {
          "text": "Wrap the input prompt inside a while true loop.",
          "refs": ["Q0009"]
        },
        {
          "text": "Read the user input.",
          "refs": ["Q0009"]
        },
        {
          "text": "Check if the input satisfies the required range (e.g., between 1,000 and 1,000,000).",
          "refs": ["Q0009"]
        },
        {
          "text": "If the input is valid, break out of the loop; otherwise, display an error message and repeat.",
          "refs": ["Q0009"]
        }
      ],
      "prerequisites": null,
      "outcomes": null,
      "content": {
        "text": "Use an infinite loop with a break statement to repeatedly ask the user for a value until it falls within the allowed range.",
        "refs": ["Q0009"]
      }
    }
  ],
